#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int d) : data(d), left(nullptr), right(nullptr) {}
};

Node* insert(Node* node, int value) {
    if (node == nullptr) {
        return new Node(value);
    }
    if (value < node->data) {
        node->left = insert(node->left, value);
    } else {
        node->right = insert(node->right, value);
    }
    return node;
}

int height(Node* node) {
    if (node == nullptr) {
        return 0;
    }
    return 1 + max(height(node->left), height(node->right));
}

int comparisons(Node* root, int value) {
    int count = 0;
    Node* cur = root;
    while (cur != nullptr) {
        count++;
        if (value == cur->data) {
            return count;
        }
        if (value < cur->data) {
            cur = cur->left;
        } else {
            cur = cur->right;
        }
    }
    return count;
}

void destroy(Node* node) {
    if (node == nullptr) {
        return;
    }
    destroy(node->left);
    destroy(node->right);
    delete node;
}

int main() {
    Node* chain = nullptr;
    int sorted[] = {10, 20, 30, 40, 50};
    for (int i = 0; i < 5; i++) {
        chain = insert(chain, sorted[i]);
    }
    Node* bushy = nullptr;
    int mixed[] = {30, 20, 40, 10, 50};
    for (int i = 0; i < 5; i++) {
        bushy = insert(bushy, mixed[i]);
    }
    cout << "Chain: height " << height(chain) << ", finding 50 takes " << comparisons(chain, 50) << " comparisons" << endl;
    cout << "Bushy: height " << height(bushy) << ", finding 50 takes " << comparisons(bushy, 50) << " comparisons" << endl;
    destroy(chain);
    destroy(bushy);
    return 0;
}
